const chain = (...steps) => (start) =>
  steps.reduceRight((value, step) => step(value), start);

const half = (n) => n / 2;
const minus = (k) => (n) => n - k;

console.log(chain(half, minus(4))(20));
console.log(chain(minus(4), half)(20));
console.log(chain(chain(half, half), minus(2))(10));
console.log(chain()(3));
